def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    last_my, last_opp = history[-1]
    if n == 2:
        return 'D' if last_opp == 'D' else 'C'

    recent = 10 if n > 10 else n
    start = n - recent

    opp_d_total = 0
    my_d_total = 0
    opp_d_recent = 0
    my_d_recent = 0
    diff = 0

    for i, h in enumerate(history):
        m = h[0]
        o = h[1]

        if o == 'D':
            opp_d_total += 1
            if i >= start:
                opp_d_recent += 1

        if m == 'D':
            my_d_total += 1
            if i >= start:
                my_d_recent += 1

        if m == 'D' and o == 'C':
            diff += 5
        elif m == 'C' and o == 'D':
            diff -= 5

    opp_d_streak = 0
    for h in reversed(history):
        if h[1] == 'D':
            opp_d_streak += 1
        else:
            break

    my_d_streak = 0
    for h in reversed(history):
        if h[0] == 'D':
            my_d_streak += 1
        else:
            break

    toler = 0
    punish = 0
    for i in range(1, n):
        if history[i - 1][0] == 'D':
            if history[i][1] == 'C':
                toler += 1
            else:
                punish += 1

    if n == 99:
        return 'D'

    if n >= 8 and (opp_d_total * 2 > n or opp_d_recent >= 6 or diff < -30):
        return 'D'

    if n >= 98 and last_opp == 'D':
        return 'D'

    exploitable = False
    if (n >= 8 and opp_d_total * 5 <= n * 2 and opp_d_recent <= 3
            and toler > 0 and punish * 2 <= toler):
        exploitable = True

    if last_opp == 'D':
        if last_my == 'D':
            if opp_d_total * 3 <= n and opp_d_streak <= 2 and my_d_streak <= 2:
                return 'C'
            return 'D'

        if history[-2] == ('D', 'C'):
            return 'C'
        if my_d_recent > 0 and opp_d_total * 4 <= n and opp_d_streak <= 2:
            return 'C'
        if opp_d_total * 10 <= n and opp_d_recent <= 1 and diff >= -15:
            return 'C'
        return 'D'

    if last_my == 'D':
        if exploitable:
            return 'D'
        return 'C'

    if exploitable:
        return 'D'

    if my_d_total == 0 and opp_d_total == 0:
        if n == 18 and rng.random() < 0.12:
            return 'D'
        if n == 70 and rng.random() < 0.12:
            return 'D'
        if n == 97 and rng.random() < 0.25:
            return 'D'

    return 'C'
